import { PUP_CIRCLES, PUP_POLY } from './pupShapes';

/**
 * The fluffy white Maltese from the reference art: a wavy, fluffy silhouette with one thick black
 * outline, two dot eyes, a little nose and a happy open mouth with a red tongue.
 *
 * The silhouette data is generated by scripts/make-pup.mjs (also used for the app icon). It is
 * drawn twice, first fat and black, then white, so all the bumps merge into one outlined shape.
 */
function Blobs() {
  return (
    <>
      <polygon points={PUP_POLY} />
      {PUP_CIRCLES.map(([x, y, r], i) => (
        <circle key={i} cx={x} cy={y} r={r} />
      ))}
    </>
  );
}

export function Pup({ size = 64, className = '' }: { size?: number; className?: string }) {
  return (
    <svg className={className} width={size} height={size} viewBox="0 0 120 120" aria-hidden focusable="false">
      <g fill="#111" stroke="#111" strokeWidth="5" strokeLinejoin="round">
        <Blobs />
      </g>
      <g fill="#fff">
        <Blobs />
      </g>
      <g fill="#111">
        <circle cx="47" cy="42" r="2.6" />
        <circle cx="71" cy="40" r="2.6" />
        <path d="M55.5 48h7a1.4 1.4 0 0 1 1.1 2.2l-3.5 4a1.4 1.4 0 0 1-2.2 0l-3.5-4a1.4 1.4 0 0 1 1.1-2.2z" />
        <path d="M49.5 55h19a9.5 9.5 0 0 1-19 0z" />
      </g>
      <path d="M54 59h10a5 5 0 0 1-10 0z" fill="#f0616f" />
    </svg>
  );
}
